<?php
namespace App\Services;
use App\Models\PromoMember;
use Illuminate\Support\Facades\DB;
class PromoAnalyticsService
{
 public function forPromo(PromoMember $promo,?string $from=null,?string $to=null):array{$q=DB::table('promo_redemptions as r')->join('transaksi as t','t.id_transaksi','=','r.id_transaksi')->where('r.id_promo',$promo->id_promo)->where('r.status','completed');if($from)$q->whereDate('r.used_at','>=',$from);if($to)$q->whereDate('r.used_at','<=',$to);$row=$q->selectRaw('COUNT(*) redemptions, COUNT(DISTINCT r.id_pelanggan) unique_members, COALESCE(SUM(r.subtotal),0) original_value, COALESCE(SUM(r.discount),0) total_discount, COALESCE(SUM(r.total_final),0) revenue')->first();$revenue=(int)round($row->revenue??0);$costRate=$promo->estimated_cost_rate===null?null:(float)$promo->estimated_cost_rate;$cost=$costRate===null?null:(int)round($revenue*$costRate);$margin=$cost===null?null:$revenue-$cost;$projection=(int)($promo->projection_margin??0);$ratio=$projection>0&&$margin!==null?$margin/$projection:null;return['redemptions'=>(int)($row->redemptions??0),'unique_members'=>(int)($row->unique_members??0),'original_value'=>(int)round($row->original_value??0),'total_discount'=>(int)round($row->total_discount??0),'revenue'=>(int)$revenue,'estimated_cost'=>$cost,'estimated_margin'=>$margin,'cost_complete'=>$cost!==null,'projection'=>['transactions'=>$promo->projection_transactions,'revenue'=>$promo->projection_revenue,'discount'=>$promo->projection_discount,'margin'=>$promo->projection_margin,'score'=>$promo->spk_score,'recommendation'=>$promo->spk_recommendation],'variance'=>['transactions'=>$this->variance($row->redemptions??0,$promo->projection_transactions),'revenue'=>$this->variance($revenue,$promo->projection_revenue),'margin'=>$this->variance($margin,$promo->projection_margin)],'performance'=>$ratio===null?'COST DATA INCOMPLETE':($ratio>=1?'ABOVE PROJECTION':($ratio>=.95?'ON TARGET':($ratio>=.8?'SLIGHTLY BELOW':'BELOW PROJECTION')))];}
 private function variance($actual,$projected):?float{return $projected===null||(float)$projected===0?null:round((((float)$actual-(float)$projected)/(float)$projected)*100,2);}
 public function dashboard():array{$month=now()->startOfMonth();$q=DB::table('promo_redemptions')->where('status','completed');return['active'=>PromoMember::where('status','aktif')->where('mulai_at','<=',now())->where('selesai_at','>=',now())->count(),'ending'=>PromoMember::where('status','aktif')->whereBetween('selesai_at',[now(),now()->addDays(30)])->count(),'redemptions_month'=>(int)(clone$q)->where('used_at','>=',$month)->count(),'discount_month'=>(int)round((clone$q)->where('used_at','>=',$month)->sum('discount')),'revenue_month'=>(int)round((clone$q)->where('used_at','>=',$month)->sum('total_final'))];}
}
